// Package water 是本地取样与超标判定的本地基线。
package water

// Ready 表示基线可以运行。
func Ready() bool { return true }

content.content:
1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16	)
17	
18	// Status 表示样品所处的判定状态。
19	type Status string
20	
21	const (
22		// StatusPending 样品已录入，尚未确认判定结果。
23		StatusPending Status = "pending"
24		// StatusConfirmed 样品已确认，判定结果已保存。
25		StatusConfirmed Status = "confirmed"
26		// StatusVoided 样品已作废，保留记录但不能再确认。
27		StatusVoided Status = "voided"
28	)
29	
30	var (
31		ErrClosed             = errors.New("water: 数据存放已关闭")
32		ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
33		ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
34		ErrUnknownPoint       = errors.New("water: 采样点未登记")
35		ErrInvalidValue       = errors.New("water: 数值只接受有限数")
36		ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
37		ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
38		ErrUnknownSample      = errors.New("water: 样品编号不存在")
39		ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
40		ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
41		ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
42		ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
43		ErrVoided             = errors.New("water: 样品已作废，不能再确认")
44		ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
45	)
46	
47	// SamplingPoint 是按编号唯一登记的采样点。
48	type SamplingPoint struct {
49		ID   string `json:"id"`
50		Name string `json:"name"`
51	}
52	
53	// Limit 是某采样点某测量项目的一版数值上限。
54	type Limit struct {
55		PointID   string    `json:"pointId"`
56		Item      string    `json:"item"`
57		Value     float64   `json:"value"`
58		Effective time.Time `json:"effective"`
59	}
60	
61	// Measurement 是样品中一个项目的测量值。
62	type Measurement struct {
63		Item  string  `json:"item"`
64		Value float64 `json:"value"`
65	}
66	
67	// ItemResult 是确认后单个项目的判定结果。
68	type ItemResult struct {
69		Item           string    `json:"item"`
70		Value          float64   `json:"value"`
71		Limit          float64   `json:"limit"`
72		LimitEffective time.Time `json:"limitEffective"`
73		Exceeded       bool      `json:"exceeded"`
74	}
75	
76	// Sample 是一份从录入、确认到作废的样品记录。
77	type Sample struct {
78		ID           string        `json:"id"`
79		PointID      string        `json:"pointId"`
80		SampledAt    time.Time     `json:"sampledAt"`
81		Measurements []Measurement `json:"measurements"`
82		Status       Status        `json:"status"`
83		Results      []ItemResult  `json:"results,omitempty"`
84		Exceeded     bool          `json:"exceeded"`
85		VoidReason   string        `json:"voidReason,omitempty"`
86	}
87	
88	// diskState 是落盘的完整数据。
89	type diskState struct {
90		Points  map[string]SamplingPoint `json:"points"`
91		Limits  map[string][]Limit       `json:"limits"` // 键仅为落盘占位，读取时按每条限值自身的采样点与项目重新分组
92		Samples map[string]*Sample       `json:"samples"`
93	}
94	
95	// limitGroup 用两个字段各自标识一组限值，避免把包含 U+0000 的文本
96	// 用单字符拼接成键时不同组合撞成同一组。
97	type limitGroup struct {
98		pointID string
99		item    string
100	}
101	
102	// Store 是绑定到某个本地目录的取样判定数据存放。
103	// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
104	type Store struct {
105		mu      sync.Mutex
106		dir     string
107		file    string
108		closed  bool
109		points  map[string]SamplingPoint
110		limits  map[limitGroup][]Limit // 按生效时间升序
111		samples map[string]*Sample
112	}
113	
114	// Open 打开（必要时创建）dir 下的本地数据存放。
115	func Open(dir string) (*Store, error) {
116		if strings.TrimSpace(dir) == "" {
117			return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
118		}
119		if err := os.MkdirAll(dir, 0o755); err != nil {
120			return nil, err
121		}
122		s := &Store{
123			dir:     dir,
124			file:    filepath.Join(dir, "water-data.json"),
125			points:  map[string]SamplingPoint{},
126			limits:  map[limitGroup][]Limit{},
127			samples: map[string]*Sample{},
128		}
129		data, err := os.ReadFile(s.file)
130		if errors.Is(err, fs.ErrNotExist) {
131			return s, nil
132		}
133		if err != nil {
134			return nil, err
135		}
136		var st diskState
137		if err := json.Unmarshal(data, &st); err != nil {
138			return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
139		}
140		if st.Points != nil {
141			s.points = st.Points
142		}
143		if st.Limits != nil {
144			// 不按落盘键分组：键可能是旧版本用单字符拼接生成的，包含 U+0000 的
145			// 不同（采样点，项目）组合会共用同一个键。以每条限值自身的两个字段为准，
146			// 让曾经被错误合并的组在重新打开时也能各自归位。
147			for _, versions := range st.Limits {
148				for _, lim := range versions {
149					g := limitGroup{pointID: lim.PointID, item: lim.Item}
150					s.limits[g] = append(s.limits[g], lim)
151				}
152			}
153			for g, versions := range s.limits {
154				sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
155				s.limits[g] = versions
156			}
157		}
158		if st.Samples != nil {
159			s.samples = st.Samples
160		}
161		return s, nil
162	}
163	
164	// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
165	func (s *Store) Close() error {
166		s.mu.Lock()
167		defer s.mu.Unlock()
168		if s.closed {
169			return nil
170		}
171		s.closed = true
172		return nil
173	}
174	
175	func clean(s string) string { return strings.TrimSpace(s) }
176	
177	// diskLimitKey 生成仅用于落盘 JSON 的分组键。带上两个字段的长度前缀，
178	// 任何包含 U+0000 的文本组合都不会撞键；读取时并不依赖该键分组。
179	func diskLimitKey(pointID, item string) string {
180		return strconv.Itoa(len(pointID)) + ":" + pointID + strconv.Itoa(len(item)) + ":" + item
181	}
182	
183	func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
184	
185	func (s *Store) checkOpenLocked() error {
186		if s.closed {
187			return ErrClosed
188		}
189		return nil
190	}
191	
192	// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
193	// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
194	func (s *Store) persistLocked() error {
195		diskLimits := make(map[string][]Limit, len(s.limits))
196		for g, versions := range s.limits {
197			diskLimits[diskLimitKey(g.pointID, g.item)] = versions
198		}
199		data, err := json.MarshalIndent(diskState{
200			Points:  s.points,
201			Limits:  diskLimits,
202			Samples: s.samples,
203		}, "", "  ")
204		if err != nil {
205			return err
206		}
207		tmp := s.file + ".tmp"
208		if err := os.WriteFile(tmp, data, 0o644); err != nil {
209			return err
210		}
211		return os.Rename(tmp, s.file)
212	}
213	
214	// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
215	// 保存和比较均使用处理后的文本；重复编号拒绝。
216	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
217		s.mu.Lock()
218		defer s.mu.Unlock()
219		if err := s.checkOpenLocked(); err != nil {
220			return SamplingPoint{}, err
221		}
222		id, name = clean(id), clean(name)
223		if id == "" || name == "" {
224			return SamplingPoint{}, ErrEmptyField
225		}
226		if _, ok := s.points[id]; ok {
227			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
228		}
229		p := SamplingPoint{ID: id, Name: name}
230		s.points[id] = p
231		if err := s.persistLocked(); err != nil {
232			delete(s.points, id)
233			return SamplingPoint{}, err
234		}
235		return p, nil
236	}
237	
238	// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
239	// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
240	func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
241		s.mu.Lock()
242		defer s.mu.Unlock()
243		if err := s.checkOpenLocked(); err != nil {
244			return Limit{}, err
245		}
246		pointID, item = clean(pointID), clean(item)
247		if pointID == "" || item == "" {
248			return Limit{}, ErrEmptyField
249		}
250		if _, ok := s.points[pointID]; !ok {
251			return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
252		}
253		if !finite(value) {
254			return Limit{}, ErrInvalidValue
255		}
256		if effective.IsZero() {
257			return Limit{}, ErrInvalidTime
258		}
259		lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
260		g := limitGroup{pointID: pointID, item: item}
261		versions := s.limits[g]
262		for _, v := range versions {
263			if v.Effective.Equal(lim.Effective) {
264				return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
265			}
266		}
267		old := s.limits[g]
268		// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
269		// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
270		versions = make([]Limit, len(old)+1)
271		copy(versions, old)
272		versions[len(old)] = lim
273		sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
274		s.limits[g] = versions
275		if err := s.persistLocked(); err != nil {
276			s.limits[g] = old
277			return Limit{}, err
278		}
279		return lim, nil
280	}
281	
282	// SubmitSample 录入一份样品，初始为待判定状态。
283	// 再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
284	// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
285	func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
286		s.mu.Lock()
287		defer s.mu.Unlock()
288		if err := s.checkOpenLocked(); err != nil {
289			return Sample{}, err
290		}
291		id, pointID = clean(id), clean(pointID)
292		if id == "" || pointID == "" {
293			return Sample{}, ErrEmptyField
294		}
295		if sampledAt.IsZero() {
296			return Sample{}, ErrInvalidTime
297		}
298		if len(measurements) == 0 {
299			return Sample{}, ErrNoMeasurements
300		}
301		ms := make([]Measurement, len(measurements))
302		seen := make(map[string]float64, len(measurements))
303		for i, m := range measurements {
304			item := clean(m.Item)
305			if item == "" {
306				return Sample{}, ErrEmptyField
307			}
308			if !finite(m.Value) {
309				return Sample{}, ErrInvalidValue
310			}
311			if _, dup := seen[item]; dup {
312				return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
313			}
314			seen[item] = m.Value
315			ms[i] = Measurement{Item: item, Value: m.Value}
316		}
317		sampledAt = sampledAt.UTC()
318	
319		if existing, ok := s.samples[id]; ok {
320			if sameSampleContent(existing, pointID, sampledAt, seen) {
321				return copySample(existing), nil
322			}
323			return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
324		}
325		if _, ok := s.points[pointID]; !ok {
326			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
327		}
328		smp := &Sample{
329			ID:           id,
330			PointID:      pointID,
331			SampledAt:    sampledAt,
332			Measurements: ms,
333			Status:       StatusPending,
334		}
335		s.samples[id] = smp
336		if err := s.persistLocked(); err != nil {
337			delete(s.samples, id)
338			return Sample{}, err
339		}
340		return copySample(smp), nil
341	}
342	
343	func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
344		if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
345			return false
346		}
347		for _, m := range s.Measurements {
348			v, ok := ms[m.Item]
349			if !ok || v != m.Value {
350				return false
351			}
352		}
353		return true
354	}
355	
356	// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
357	// 测量值大于上限才超标，任一项目超标则整份样品超标。
358	// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
359	// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
360	func (s *Store) Confirm(id string) (Sample, error) {
361		s.mu.Lock()
362		defer s.mu.Unlock()
363		if err := s.checkOpenLocked(); err != nil {
364			return Sample{}, err
365		}
366		id = clean(id)
367		if id == "" {
368			return Sample{}, ErrEmptyField
369		}
370		smp, ok := s.samples[id]
371		if !ok {
372			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
373		}
374		switch smp.Status {
375		case StatusVoided:
376			return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
377		case StatusConfirmed:
378			return copySample(smp), nil
379		}
380	
381		results := make([]ItemResult, 0, len(smp.Measurements))
382		exceeded := false
383		for _, m := range smp.Measurements {
384			lim, ok := applicableLimit(s.limits[limitGroup{pointID: smp.PointID, item: m.Item}], smp.SampledAt)
385			if !ok {
386				return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
387			}
388			ex := m.Value > lim.Value
389			if ex {
390				exceeded = true
391			}
392			results = append(results, ItemResult{
393				Item:           m.Item,
394				Value:          m.Value,
395				Limit:          lim.Value,
396				LimitEffective: lim.Effective,
397				Exceeded:       ex,
398			})
399		}
400		smp.Results = results
401		smp.Exceeded = exceeded
402		smp.Status = StatusConfirmed
403		if err := s.persistLocked(); err != nil {
404			smp.Results = nil
405			smp.Exceeded = false
406			smp.Status = StatusPending
407			return Sample{}, err
408		}
409		return copySample(smp), nil
410	}
411	
412	// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
413	// 采样时间恰好等于生效时间时使用该版新值。
414	func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
415		best := -1
416		for i, v := range versions {
417			if v.Effective.After(at) {
418				break
419			}
420			best = i
421		}
422		if best < 0 {
423			return Limit{}, false
424		}
425		return versions[best], true
426	}
427	
428	// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
429	// 作废后保留测量、原因和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
430	func (s *Store) Void(id, reason string) (Sample, error) {
431		s.mu.Lock()
432		defer s.mu.Unlock()
433		if err := s.checkOpenLocked(); err != nil {
434			return Sample{}, err
435		}
436		id, reason = clean(id), clean(reason)
437		if id == "" || reason == "" {
438			return Sample{}, ErrEmptyField
439		}
440		smp, ok := s.samples[id]
441		if !ok {
442			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
443		}
444		if smp.Status == StatusVoided {
445			if smp.VoidReason == reason {
446				return copySample(smp), nil
447			}
448			return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
449		}
450		oldStatus := smp.Status
451		smp.Status = StatusVoided
452		smp.VoidReason = reason
453		if err := s.persistLocked(); err != nil {
454			smp.Status = oldStatus
455			smp.VoidReason = ""
456			return Sample{}, err
457		}
458		return copySample(smp), nil
459	}
460	
461	// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
462	func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
463		s.mu.Lock()
464		defer s.mu.Unlock()
465		if err := s.checkOpenLocked(); err != nil {
466			return nil, err
467		}
468		pointID = clean(pointID)
469		var list []Sample
470		for _, smp := range s.samples {
471			if smp.PointID == pointID {
472				list = append(list, copySample(smp))
473			}
474		}
475		sortSamples(list)
476		return list, nil
477	}
478	
479	// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
480	// 没有已确认且未作废的样品时 ok 为 false。
481	func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
482		s.mu.Lock()
483		defer s.mu.Unlock()
484		if err := s.checkOpenLocked(); err != nil {
485			return Sample{}, false, err
486		}
487		pointID = clean(pointID)
488		var list []Sample
489		for _, s := range s.samples {
490			if s.PointID == pointID && s.Status == StatusConfirmed {
491				list = append(list, copySample(s))
492			}
493		}
494		if len(list) == 0 {
495			return Sample{}, false, nil
496		}
497		sortSamples(list)
498		return list[0], true, nil
499	}
500	
501	func sortSamples(list []Sample) {
502		sort.Slice(list, func(i, j int) bool {
503			a, b := list[i], list[j]
504			if !a.SampledAt.Equal(b.SampledAt) {
505				return a.SampledAt.After(b.SampledAt)
506			}
507			return a.ID < b.ID
508		})
509	}
510	
511	func copySample(s *Sample) Sample {
512		c := *s
513		c.Measurements = append([]Measurement(nil), s.Measurements...)
514		c.Results = append([]ItemResult(nil), s.Results...)
515		return c
516	}
517

